/* ROVO V5 — reserved, mechanical control panel style */
.rv-name-subline{display:flex;align-items:center;gap:12px;margin:-7px 0 22px;padding:7px 10px;border-left:2px solid #7fb9ce;color:#a8bfd1;font-size:11px;letter-spacing:.1px}
.rv-name-strong{font-size:12px;letter-spacing:1.4px;font-weight:850;color:#a2d2e0}
.rv-system-status{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}
.rv-system-state{display:flex;gap:8px;flex-wrap:wrap;align-items:center;background:#233548;border:1px solid #365269;border-radius:7px;padding:13px 11px;color:#dce8ee;font-size:12px}
.rv-system-state strong{flex-basis:100%;font-size:13px;padding-left:13px;color:#bdd0de}
.rv-system-indicator{width:6px;height:6px;background:#667988;border-radius:50%}.rv-system-indicator.on{background:#71c7aa}
.rv-motion-illustration{display:flex;flex-direction:column}
.rv-robot-stage{height:230px;position:relative;overflow:hidden;margin:10px 0 4px;border-radius:8px;background:radial-gradient(ellipse at 50% 35%,#294557,#142433 78%);border:1px solid #3a5265}
.rv-robot-guide{position:absolute;pointer-events:none;opacity:.22}.rv-robot-guide-vert{top:10px;bottom:10px;width:1px;border-left:1px dashed #9eb3c0;left:50%}.rv-robot-guide-horz{left:15px;right:15px;border-top:1px dashed #9eb3c0;top:51%}
.rv-robot-head{width:150px;height:112px;border:7px solid #506b83;border-radius:35px;background:#101c2a;position:absolute;z-index:3;top:40px;left:calc(50% - 75px);display:grid;place-items:center;box-shadow:0 8px 24px #0005;transition:transform .23s cubic-bezier(.23,.75,.3,1)}
.rv-robot-screen{width:122px;height:85px;border-radius:26px;background:#07111b;display:flex;align-items:center;justify-content:center;gap:27px;position:relative}
.rv-robot-eye{background:#90e2e0;width:17px;height:28px;border-radius:20px;box-shadow:0 0 10px #7bc8ce5c;animation:rv-eye-blink 7s infinite}
.rv-robot-mouth{position:absolute;width:23px;height:9px;border-bottom:3px solid #8bcece;border-radius:0 0 50% 50%;bottom:15px;left:calc(50% - 11px)}
.rv-robot-neck{width:34px;height:65px;background:#63798c;position:absolute;z-index:1;top:127px;left:calc(50% - 17px);border-radius:6px}
.rv-robot-base{width:100px;height:22px;background:#516d82;position:absolute;z-index:2;bottom:11px;left:calc(50% - 50px);border-radius:10px 10px 3px 3px}
.rv-robot-coordinates{display:flex;gap:9px;margin:6px 0;justify-content:space-between}
.rv-robot-coordinates>div{flex:1;background:#243748;padding:9px 11px;border-radius:7px;display:flex;justify-content:space-between;gap:5px;align-items:center;font-size:11px}
.rv-robot-coordinates b{font-size:12px;color:#dbeef3}
.rv-main-expression{display:flex;flex-direction:column;align-items:center;gap:10px;margin:18px 0 18px;padding:21px 15px;border-radius:9px;background:#132333;border:1px solid #334b5f}
.rv-expression-robot{position:relative;width:220px;height:133px;background:#07121e;border:8px solid #4f6880;border-radius:37px;box-shadow:inset 0 0 20px #2b5161,0 10px 24px #0004;overflow:hidden}
.rv-expression-name{font-size:14px;font-weight:750;color:#edf7fa}
.rv-face-eye{position:absolute;top:39%;height:37px;width:26px;border-radius:55%;background:#80dadd;box-shadow:0 0 13px #7ad0db66;animation:rv-eye-blink 6.8s infinite;transition:.3s all}
.rv-eye-left{left:26%}.rv-eye-right{right:26%}
.rv-face-mouth{position:absolute;width:39px;height:13px;bottom:17%;left:calc(50% - 19px);border-bottom:4px solid #80dadd;border-radius:0 0 55% 55%;transition:.3s all}
.rv-expression-happy .rv-face-eye{height:20px;top:49%;border-radius:50% 50% 20% 20%;transform:rotate(-8deg)}
.rv-expression-happy .rv-face-mouth{width:54px;left:calc(50% - 27px);height:19px;border-bottom-width:5px}
.rv-expression-curious .rv-eye-left{transform:scale(1.1)}.rv-expression-curious .rv-eye-right{transform:scale(.8) translateY(5px)}
.rv-expression-curious .rv-face-mouth{width:17px;left:calc(50% - 8px);border-bottom-width:3px;border-radius:50%}
.rv-expression-sleepy .rv-face-eye{height:9px;top:55%;border-radius:6px;animation:none}.rv-expression-sleepy .rv-face-mouth{width:24px;left:calc(50% - 12px);height:4px}
.rv-expression-surprised .rv-face-eye{width:30px;height:42px;top:35%}.rv-expression-surprised .rv-face-mouth{width:21px;height:21px;left:calc(50% - 11px);bottom:15%;border:4px solid #80dadd;border-radius:50%}
.rv-expression-blink .rv-eye-left{height:7px;top:55%;animation:none}.rv-expression-blink .rv-eye-right{animation:rv-eye-blink 2.3s infinite}.rv-expression-blink .rv-face-mouth{width:30px;left:calc(50% - 15px)}
@keyframes rv-eye-blink{0%,43%,45%,100%{transform:scaleY(1)}44%{transform:scaleY(.12)}}
.rv-mini-robot{position:relative;width:98px;height:65px;flex:none;background:#0c1826;border:3px solid #537088;border-radius:21px;display:block}
.rv-mini-robot .rv-face-eye{top:39%;height:19px;width:12px;box-shadow:none}.rv-mini-robot .rv-eye-left{left:27%}.rv-mini-robot .rv-eye-right{right:27%}
.rv-mini-robot .rv-face-mouth{width:20px;height:7px;bottom:12%;left:calc(50% - 10px);border-bottom-width:2px}
.rv-mini-robot.rv-expression-happy .rv-face-eye{height:10px;top:50%}.rv-mini-robot.rv-expression-surprised .rv-face-mouth{height:9px;width:9px;left:calc(50% - 5px);border-width:2px}
.rv-mini-robot.rv-expression-sleepy .rv-face-eye{height:5px;top:50%}.rv-mini-robot.rv-expression-blink .rv-eye-left{height:4px;top:52%}
.rv-model-summary{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:17px 0}
.rv-model-summary>div{background:#233447;border-radius:7px;border:1px solid #385368;padding:11px 12px;display:flex;flex-direction:column;gap:5px;min-width:0}
.rv-model-summary strong{overflow-wrap:anywhere;font-size:12px;color:#e4f0f6}
.rv-empty{font-size:12px;line-height:1.7;padding:15px;border:1px dashed #456174;border-radius:8px;color:#b3c6d4}
@media(max-width:1050px){.rv-system-status{grid-template-columns:repeat(3,minmax(0,1fr))}}
